def waterline_y(x):
    step=.5
    i=max(0,min(len(POINTS)-2,int((x-POINTS[0][0])/step)))
    x0,y0=POINTS[i];x1,y1=POINTS[i+1]
    t=max(0,min(1,(x-x0)/step))
    def slope(index):
        if index==0:return (POINTS[1][1]-POINTS[0][1])/step
        if index==len(POINTS)-1:return (POINTS[-1][1]-POINTS[-2][1])/step
        a=(POINTS[index][1]-POINTS[index-1][1])/step
        b=(POINTS[index+1][1]-POINTS[index][1])/step
        return 2*a*b/(a+b) if a*b>0 else 0
    return (2*t**3-3*t*t+1)*y0+(t**3-2*t*t+t)*step*slope(i)+(-2*t**3+3*t*t)*y1+(t**3-t*t)*step*slope(i+1)
